window.docContents[232].resolve({"/Lecture-1___-Motivation-and-Propositional-Logic/Natural-Deduction/#Formal-Software-Verification--Lecture-1___-Motivation-and-Propositional-Logic--Natural-Deduction--Implication":{"contents":"To introduce P → Q, assume P, derive Q, and discharge the assumption. To eliminate it, apply an implication to a proof of its antecedent, the rule of modus ponens.\n\n   [P]\n    ⋮\n    Q                   P → Q    P\n  ───────  →I          ─────────────  →E\n   P → Q                     Q\n\n\n","context":"Formal Software Verification\u0009Lecture 1: Motivation and Propositional Logic\u0009Natural Deduction","header":"1.5.1. Implication","id":"/Lecture-1___-Motivation-and-Propositional-Logic/Natural-Deduction/#Formal-Software-Verification--Lecture-1___-Motivation-and-Propositional-Logic--Natural-Deduction--Implication"}});